from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/upload")
async def upload(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file": len(file)}

