import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_func():
    return 1

def sync_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def test_sync_wrapper_async_func():
    wrapped = sync_wrapper(async_func)
    dependant = Dependant(call=wrapped)
    print(f"Sync wrapper around async func: is_coroutine_callable = {dependant.is_coroutine_callable}")
    assert dependant.is_coroutine_callable is True

def test_partial_sync_wrapper_async_func():
    wrapped = sync_wrapper(async_func)
    p_wrapped = partial(wrapped)
    dependant = Dependant(call=p_wrapped)
    print(f"Partial of sync wrapper around async func: is_coroutine_callable = {dependant.is_coroutine_callable}")
    assert dependant.is_coroutine_callable is True

async def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

def sync_func():
    return 1

def test_async_wrapper_sync_func():
    # This is a bit tricky because async_wrapper is async, so it needs to be called
    # But the problem is about the resulting callable.
    # Let's just use a simple async wrapper.
    async def wrapper():
        return sync_func()

    dependant = Dependant(call=wrapper)
    print(f"Async wrapper around sync func: is_coroutine_callable = {dependant.is_coroutine_callable}")
    assert dependant.is_coroutine_callable is True

if __name__ == "__main__":
    try:
        test_sync_wrapper_async_func()
        print("test_sync_wrapper_async_func passed")
    except Exception as e:
        print(f"test_sync_wrapper_async_func failed: {e}")

    try:
        test_partial_sync_wrapper_async_func()
        print("test_partial_sync_wrapper_async_func passed")
    except Exception as e:
        print(f"test_partial_sync_wrapper_async_func failed: {e}")

    try:
        test_async_wrapper_sync_func()
        print("test_async_wrapper_sync_func passed")
    except Exception as e:
        print(f"test_async_wrapper_sync_func failed: {e}")

