        assert str(e) == "Query param 'data' must be of one of the supported types"
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e
    else:
        print("No AssertionError raised!")
        raise AssertionError("No AssertionError raised!")

if __name__ == "__main__":
    try:
        test_invalid_query_param_error_message()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)

