from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/upload1")
async def upload1(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

