        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"upload2 (Form then File) - Response: {response.status_code}, Body: {response.json() if response.status_code == 200 else response.text}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_file_then_form()
        test_form_then_file()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")

