from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_with_at():
    highlighter = ReprHighlighter()
    url = "https://user:pass@example.com"
    text = Text(url)
    highlighter.highlight(text)

    # Check if the url is highlighted
    # The expected span should be from 0 to len(url) with style "repr.url"
    found = False
    for span in text.spans:
        if span.style == "repr.url":
            print(f"Found span: {span}")
            found = True

    if not found:
        print("URL with @ was not highlighted")
    else:
        print("URL with @ was highlighted")

if __name__ == "__main__":
    test_url_with_at()

